"""Promote the fourth-turning-value route and the headline gelfand_turning_values from Work to Checked by script
(run 2026-11-20T1028Z; after runs/2026-11-18T1028Z/scripts/promote_gelfand_values.py). Copies
Work/Math/{GLam3Data,GLam3Chain,GelfandLam3,GelfandTurningValues}.lean to Checked/Math/, renames the Work
namespaces (GLamCell, GLamBands are already in Checked), replaces each module doc by one without numerals."""
import re
mods = ['GLam3Data', 'GLam3Chain', 'GelfandLam3', 'GelfandTurningValues']
ren = mods + ['GLamCell', 'GLamBands', 'GLamChain']
docs = {
 'GLam3Data': 'Gelfand problem, `GLam3Data`: validated homology cells of the regular isothermal solution from the end of `GLamChain` (beyond the third turning point of the branch parameter) to beyond the fourth, as data (generator `runs/2026-11-20T1028Z/scripts/gen_gl.py` with START=end, emitter `emit_gl3.py`), each segment decided by kernel evaluation with its invariant of `GLamCell`. Promoted from `Work/Math/GLam3Data.lean` (run 2026-11-20T1028Z).',
 'GLam3Chain': 'Gelfand problem, `GLam3Chain`: the cells of `GLam3Data` chained along every solution of the homology system that starts in the first cell\'s input box, the end box of `GLamChain` (generated by `runs/2026-11-20T1028Z/scripts/emit_gl3.py`). Promoted from `Work/Math/GLam3Chain.lean` (run 2026-11-20T1028Z).',
 'GelfandLam3': 'Gelfand problem, `GelfandLam3`: the value of the branch parameter λ(s) = s² e^{w(s)} of the regular isothermal solution at its fourth turning point, for every sequence of turning points with the monotonicity pattern of `Checked.Math.GelfandExtrema.gelfand_extrema`. Route: the route of `Checked.Math.GLamBands.bands`, continued by the certified homology cells of `GLam3Chain` from the end of `GLamChain` (v above two up to the bracket, u below one on the bracket, v below two at its end), the zero of v − two in the bracket by the intermediate value theorem, identified with the fourth given turning point by strict monotonicity of λ at two points, and λ = two times u at a zero of v − two. Promoted from `Work/Math/GelfandLam3.lean` (run 2026-11-20T1028Z).',
 'GelfandTurningValues': 'Gelfand problem in the three-dimensional ball, `GelfandTurningValues`: the turning sequence of the radial solution branch of `Checked.Math.GelfandExtrema.gelfand_extrema`, with the value of the branch parameter enclosed at its first turning points (the four values of the conclusion). Promoted from `Work/Math/GelfandTurningValues.lean` (frozen, proved and audited by run 2026-11-20T1028Z); the route is `Checked.Math.GelfandExtremaMain.main`, `Checked.Math.GLamBands.bands` and `Checked.Math.GelfandLam3.lam3_band`.',
}
for m in mods:
    s = open('Work/Math/%s.lean' % m).read()
    for n in ren:
        s = s.replace('Work.Math.%s' % n, 'Checked.Math.%s' % n)
    s, k = re.subn(r'/-!.*?-/', lambda _: '/-! ' + docs[m] + ' -/', s, count=1, flags=re.S)
    assert k == 1
    s = s.rstrip('\n') + '\n'
    assert 'Work.' not in s, m
    assert 'import Mathlib\n' not in s, m
    open('Checked/Math/%s.lean' % m, 'w').write(s)
print('ok')
